import { PutItemCommand } from 'dynamodb-toolbox/entity/actions/put';
import { ScanCommand } from 'dynamodb-toolbox/table/actions/scan';
import { MODELO_ACTUACION, MODELO_FESTIVAL, TABLA_ACTUACIONES } from '../../models/festival-actuacion.model.mjs';

export async function crearActuacionRepository(actuacion) {
  await MODELO_ACTUACION.build(PutItemCommand)
    .item(actuacion)
    .options({ condition: { attr: 'actuacionId', exists: false } })
    .send();
}

export async function listarActuacionesRepository() {
  const { Items = [] } = await TABLA_ACTUACIONES.build(ScanCommand)
    .entities(MODELO_ACTUACION)
    .options({ consistent: true })
    .send();
  return Items;
}

